SELECT job_title, CASE WHEN salary >= 152000 THEN 'high' WHEN salary >= 49000 THEN 'mid' ELSE 'low' END salary_bucket, ROUND(STDDEV(salary), 2) stddev_salary, MAX(salary) max_salary, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(job_title))) job_title_values FROM employees WHERE manager_id IN (13, 15, 23, 34) GROUP BY job_title, CASE WHEN salary >= 152000 THEN 'high' WHEN salary >= 49000 THEN 'mid' ELSE 'low' END HAVING max_salary > 124000 ORDER BY job_title_values, job_title, salary_bucket LIMIT 5;
